//! M3-08 acceptance: every audit list answers in under 200 ms over 100k rows per table, on
//! SQLite, through the whole stack (gate, query, count, view). The data is generated by
//! the database itself (one `INSERT .. SELECT` per table). PostgreSQL runs the same queries
//! for their answers only: its timing depends on the machine and the server, not on us.
#![allow(clippy::unwrap_used, clippy::panic, clippy::print_stderr)]

mod common;

use std::time::{Duration, Instant};

use common::audit_rows::T0;
use common::{Console, Harness, harness};
use deskhaven_admin_api::AdminRoutes;
use deskhaven_core::users::Role;
use deskhaven_db::testing::{Backend, TestDb, each_migrated_backend};
use sea_orm::ConnectionTrait;

const ROWS: i64 = 100_000;
const BUDGET: Duration = Duration::from_millis(200);
const AUDIT: &str = "/admin/api/v1/audit";
/// Rows are one second apart from [`T0`].
const STEP_MS: i64 = 1000;

/// `INSERT` of [`ROWS`] rows into `table`: `columns` are the names, `values` the expressions
/// over the series `i`.
fn generate(table: &str, columns: &str, values: &str) -> String {
    format!(
        "WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < {ROWS}) \
         INSERT INTO {table} ({columns}) SELECT {values} FROM n"
    )
}

fn statements(user: i64) -> Vec<String> {
    let created = format!("{T0} + i * {STEP_MS}");
    vec![
        generate(
            "connection_sessions",
            "guid, device_rustdesk_id, conn_id, session_id, peer_rustdesk_id, peer_name, \
             controller_user_id, conn_type, created_at",
            &format!(
                "'g' || i, 'd' || (i % 500), i, '' || i, 'p' || (i % 1000), \
                 'peer ' || (i % 1000), CASE WHEN i % 10 = 0 THEN {user} ELSE NULL END, \
                 i % 5, {created}"
            ),
        ),
        generate(
            "file_transfers",
            "device_rustdesk_id, peer_rustdesk_id, conn_id, direction, path, is_file, \
             file_count, files, created_at",
            &format!(
                "'d' || (i % 500), 'p' || (i % 1000), i, \
                 CASE WHEN i % 2 = 0 THEN 'send' ELSE 'receive' END, '/tmp/file' || i, \
                 (i % 2 = 0), 1, '[[\"a\",1]]', {created}"
            ),
        ),
        generate(
            "alarms",
            "device_rustdesk_id, typ, info, conn_id, created_at",
            &format!("'d' || (i % 500), i % 11, '{{}}', i, {created}"),
        ),
        generate(
            "login_events",
            "user_id, username_attempted, method, result, client, created_at",
            &format!(
                "CASE WHEN i % 10 = 0 THEN {user} ELSE NULL END, 'name' || (i % 1000), \
                 'password', CASE WHEN i % 3 = 0 THEN 'success' ELSE 'invalid_credentials' END, \
                 CASE WHEN i % 2 = 0 THEN 'console' ELSE 'rustdesk' END, {created}"
            ),
        ),
        generate(
            "console_audit",
            "actor_kind, actor_id, action, target_type, target_id, created_at",
            &format!(
                "'user', {user}, CASE WHEN i % 4 = 0 THEN 'user.update' ELSE 'device.update' END, \
                 'device', '' || i, {created}"
            ),
        ),
    ]
}

async fn seed(h: &Harness, user: i64) {
    for sql in statements(user) {
        h.state.db.execute_unprepared(&sql).await.unwrap();
    }
}

/// `(path, query)` pairs: the default view, every filter and a deep page of each list.
fn queries(user: i64) -> Vec<(&'static str, String)> {
    let window = format!("from={}&to={}", T0 + 5000 * STEP_MS, T0 + 6000 * STEP_MS);
    let deep = "page=400&page_size=200";
    let all = vec![
        ("connections", String::new()),
        ("connections", "device=d7".to_owned()),
        ("connections", format!("user={user}")),
        ("connections", "conn_type=3".to_owned()),
        ("connections", window.clone()),
        ("connections", deep.to_owned()),
        ("connections", "q=peer%2077".to_owned()),
        ("files", String::new()),
        ("files", "device=d7".to_owned()),
        ("files", "direction=send".to_owned()),
        ("files", window.clone()),
        ("files", deep.to_owned()),
        ("files", "q=file777".to_owned()),
        ("alarms", String::new()),
        ("alarms", "device=d7".to_owned()),
        ("alarms", "typ=3".to_owned()),
        ("alarms", window.clone()),
        ("alarms", deep.to_owned()),
        ("logins", String::new()),
        ("logins", format!("user={user}")),
        ("logins", "result=success".to_owned()),
        ("logins", "client=console&method=password".to_owned()),
        ("logins", window.clone()),
        ("logins", deep.to_owned()),
        ("logins", "q=name77".to_owned()),
        ("console", String::new()),
        ("console", format!("user={user}")),
        ("console", "action=user.update".to_owned()),
        ("console", "target_type=device".to_owned()),
        ("console", window),
        ("console", deep.to_owned()),
        ("console", "q=update".to_owned()),
    ];
    all
}

async fn timed(h: &Harness, admin: &Console, kind: &str, query: &str) -> (Duration, u64) {
    let started = Instant::now();
    let reply = h.get(&format!("{AUDIT}/{kind}?{query}"), admin).await;
    let elapsed = started.elapsed();
    assert_eq!(reply.status, 200, "{kind}?{query}: {}", reply.body);
    (elapsed, reply.body["total"].as_u64().unwrap())
}

#[tokio::test]
async fn lists_over_100k_rows_per_table_answer_within_the_budget() {
    each_migrated_backend(async |db: &TestDb| {
        let h = harness(db, AdminRoutes::new()).await;
        let admin = h.console("adm", Role::Admin).await;
        seed(&h, admin.user_id).await;

        let mut slow = Vec::new();
        for (kind, query) in queries(admin.user_id) {
            let (elapsed, total) = timed(&h, &admin, kind, &query).await;
            eprintln!("{} {kind}?{query}: {elapsed:?} (total {total})", db.backend);
            assert!(total > 0, "{kind}?{query} matched nothing");
            if elapsed > BUDGET {
                slow.push(format!("{kind}?{query}: {elapsed:?}"));
            }
        }

        if db.backend == Backend::Sqlite {
            assert!(slow.is_empty(), "over {BUDGET:?}: {slow:#?}");
        }
    })
    .await;
}
